from pathlib import Path
import json,csv,hashlib,collections
B=Path(__file__).parent;R=B/'raw-evidence'
archive=json.loads((R/'archive-independent-results.json' if (R/'archive-independent-results.json').exists() else R/'independent-results.json').read_text());(R/'archive-independent-results.json').write_text(json.dumps(archive,indent=2));pixels={x['tic']:x for x in json.loads((R/'pixel-independent-results.json').read_text())};combined=[]
for x in archive:
 if x.get('measurements'):combined.append(x)
 else:
  z=pixels[x['tic']].copy();z['archive_inventory_error']=x.get('error');combined.append(z)
(R/'independent-results.json').write_text(json.dumps(combined,indent=2))
p=B/'make_reports.py';s=p.read_text();s=s.replace('raw-evidence/helper-summary.json and helper review artifacts','raw-evidence/rawhelper-summary.md and pixel-independent-results.json');p.write_text(s)
